result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hll.py", "content": """"HyperLogLog: cardinality estimation, per Flajolet et al. (2007).

Python stdlib only. Uses blake2b to produce 64-bit hashes.
"""

import math
from hashlib import blake2b


def _hash64(item):
    """Stable 64-bit hash of `item` via blake2b."""
    data = repr(item).encode("utf-8")
    return int.from_bytes(blake2b(data, digest_size=8).digest(), "big")


class HLL:
    def __init__(self, p=14):
        if not (4 <= p <= 16):
            raise ValueError("p must be in [4, 16]")
        self.p = p
        self.m = 1 << p  # number of registers
        self.registers = bytearray(self.m)  # exactly 2^p bytes

    # -- hashing helpers ---------------------------------------------------

    def _index_and_rank(self, h):
        """Split 64-bit hash into register index and rho value."""
        idx = h >> (64 - self.p)                      # top p bits
        w = (h << self.p) & ((1 << 64) - 1)           # remaining 64-p bits
        # rho = position of leftmost 1-bit in w (1-indexed), capped at 64-p+1
        if w == 0:
            rank = 64 - self.p + 1
        else:
            rank = 64 - self.p - w.bit_length() + 2
        return idx, rank

    # -- core API -----------------------------------------------------------

    def add(self, item):
        h = _hash64(item)
        idx, rank = self._index_and_rank(h)
        if rank > self.registers[idx]:
            self.registers[idx] = rank

    def estimate(self):
        m = self.m
        regs = self.registers
        alpha_m = self._alpha(m)
        e = alpha_m * m * m / sum(2.0 ** -r for r in regs)
        zeros = regs.count(0)
        if e <= 2.5 * m and zeros > 0:
            # small-range correction: linear counting
            return m * math.log(m / zeros)
        return e

    @staticmethod
    def _alpha(m):
        if m == 16:
            return 0.673
        if m == 32:
            return 0.697
        if m == 64:
            return 0.709
        return 0.7213 / (1.0 + 1.079 / m)

    def merge(self, other):
        """Return a new HLL equal to the union of self and other."""
        if not isinstance(other, HLL) or other.p != self.p:
            raise ValueError("can only merge HLL instances with the same p")
        merged = HLL(self.p)
        merged.registers = bytearray(
            max(a, b) for a, b in zip(self.registers, other.registers)
        )
        return merged
